<?php require_once 'bootstrap.php';$u=require_admin();$msg='';$scope=user_club_sic($u['sic_id']);if(!acl_can($u['sic_id'],'registry','READ',$scope,$u['sic_id'])&&!has_role($u['sic_id'],'SUPERADMIN')){http_response_code(403);exit('Accesso non autorizzato.');}$recovery='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$kind=$_POST['kind']??'';if($kind==='USER'){$email=trim($_POST['email']??'');$name=trim($_POST['name']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$name==='')throw new RuntimeException('Dati utente non validi');$pwd=bin2hex(random_bytes(6));$recovery=create_recovery_code();$sid=sic_id();db()->prepare('INSERT INTO users(sic_id,email,display_name,password_hash,recovery_code_hash,recovery_code_changed_at) VALUES(?,?,?,?,?,CURRENT_TIMESTAMP)')->execute([$sid,$email,$name,password_hash($pwd,PASSWORD_DEFAULT),password_hash($recovery,PASSWORD_DEFAULT)]);db()->prepare("INSERT INTO user_roles(user_sic_id,role_code,status) VALUES(?, 'USER','ACTIVE')")->execute([$sid]);audit($u['sic_id'],'CREATE_USER',$sid);$msg='Utente creato. Password iniziale: '.$pwd;}elseif($kind==='FAMILY'){$sid=sic_id();db()->prepare('INSERT INTO families(sic_id,name,club_sic_id) VALUES(?,?,?)')->execute([$sid,trim($_POST['name']),trim($_POST['club_sic_id'])?:null]);$msg='Famiglia creata: '.$sid;}elseif($kind==='PROFESSIONAL'){$sid=sic_id();db()->prepare('INSERT INTO professionals(sic_id,profession,organization,territory,verification_status) VALUES(?,?,?,?,?)')->execute([$sid,trim($_POST['profession']),trim($_POST['organization']),trim($_POST['territory']),'UNVERIFIED']);$msg='Professionista registrato come UNVERIFIED: '.$sid;}}$counts=['Utenti'=>(int)db()->query('SELECT COUNT(*) FROM users')->fetchColumn(),'Famiglie'=>(int)db()->query('SELECT COUNT(*) FROM families')->fetchColumn(),'Professionisti'=>(int)db()->query('SELECT COUNT(*) FROM professionals')->fetchColumn(),'Club'=>(int)db()->query("SELECT COUNT(*) FROM dependex_world_registry WHERE network_level='LOCAL_CLUB'")->fetchColumn()];$pageTitle='Anagrafe';require '_header.php';?>
<section class="section-head"><div><span class="eyebrow">Global Registry</span><h1>Anagrafe</h1><p>User, famiglie, Club e professionisti con SIC-ID e status separati.</p></div></section><section class="metric-grid"><?php foreach($counts as $k=>$v):?><div class="metric"><b><?=$v?></b><span><?=h($k)?></span></div><?php endforeach;?></section><?php if($msg):?><div class="success"><?=h($msg)?></div><?php endif;?><?php if($recovery):?><div class="recovery-code"><?=h($recovery)?></div><?php endif;?>
